'use strict';
const $ = (id) => document.getElementById(id);
const state = {snapshot:null, selected:null, busy:false, lastRender:'', timer:null, generation:0};
const labels = {pending:'未着手',queued:'開始待ち',running:'実行中',active:'実行中',completed:'完了',done:'完了',waiting_approval:'承認待ち',pending_approval:'承認待ち',waiting:'待機中',approved:'承認済み',rejected:'却下',paused:'一時停止',stopped:'停止確認済み',agent_stopped:'担当の停止確認済み',interrupted:'引き継ぎ待ち',revision_changed:'指示の版が変更されています',superseded:'新しい判断へ引き継ぎ済み',unknown:'結果不明',failed:'失敗',cancelled:'取り消し',ready:'開始可能',run_started:'計画の実行開始',approval_required:'本人の判断待ち',approval_decided:'本人の判断を反映',task_started:'作業開始',task_completed:'作業完了',run_completed:'計画の完了',demo_seeded:'合成の案件を準備'};
function node(tag, text, className) { const el=document.createElement(tag); if(text!==undefined)el.textContent=String(text); if(className)el.className=className; return el; }
function status(text) {return node('span',labels[text]||text||'不明',`status ${/^[a-z_]+$/.test(text||'')?text:''}`);}
function message(id,text){$(id).textContent=text;$(id).hidden=!text;}
function button(text,fn,kind='secondary'){const el=node('button',text,kind);el.type='button';el.disabled=state.busy;el.addEventListener('click',fn);return el;}
async function api(path,options){const response=await fetch(path,{cache:'no-store',...options});let data;try{data=await response.json();}catch{throw new Error('応答を読み取れません。実行結果は再送せず、最新の状態で確認してください。');}if(!response.ok)throw new Error(data.error?.message||'操作に失敗しました。');return data;}
function id(){return crypto.randomUUID?crypto.randomUUID():`req_${Date.now()}_${Math.random().toString(36).slice(2)}`;}
async function act(action,args){if(state.busy)return;state.busy=true;state.lastRender='';render();message('error','');message('notice','');try{await api('/api/actions',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,request_id:id(),...args})});message('notice','操作の応答を受け取りました。最新の状態を確認してください。');}catch(error){message('error',`${error.message} 同じ操作は自動再送していません。`);}finally{state.busy=false;await refresh();}}
async function documentOpen(documentId){try{const result=await api(`/api/documents/${encodeURIComponent(documentId)}`);const doc=result.document||result.data||result;$('document-title').textContent=doc.title||'原文';$('document-revision').textContent=`合成の原文 / 版 ${doc.revision??'不明'}`;$('document-body').textContent=doc.body??'本文を取得できません。';$('document-surface').hidden=false;$('document-surface').scrollIntoView({behavior:'smooth',block:'start'});}catch(error){message('error',error.message);}}
function listEvents(target,rows){const box=$(target);box.replaceChildren();for(const event of rows.slice(-20).reverse()){const item=node('li');const kind=event.kind||event.type||event.action||event.event_type||'記録';item.append(node('strong',labels[kind]||kind));if(event.body||event.message)item.append(node('div',event.body||event.message));if(event.task_id)item.append(node('div',`作業: ${event.task_id}`));if(event.created_at||event.at)item.append(node('time',event.created_at||event.at));box.append(item);}if(!rows.length)box.append(node('li','まだ記録はありません。','empty'));}
function render(){const snap=state.snapshot;if(!snap)return;const key=JSON.stringify([snap,state.selected,state.busy]);if(key===state.lastRender)return;state.lastRender=key;const plans=snap.plans||[],tasks=snap.tasks||[],runs=snap.runs||[],approvals=snap.approvals||[];if(!plans.some(p=>p.id===state.selected))state.selected=plans[0]?.id||null;
 $('running-count').textContent=runs.filter(r=>['active','running'].includes(r.status)).length;$('approval-count').textContent=approvals.filter(a=>['pending','waiting','waiting_approval','pending_approval'].includes(a.status)).length;$('notification-count').textContent=(snap.notifications||[]).length;
 const planBox=$('plans');planBox.replaceChildren();for(const project of snap.projects||[]){planBox.append(node('div',project.title||project.id,'project-label'));for(const plan of plans.filter(p=>p.project_id===project.id)){const b=button(plan.title,()=>{state.selected=plan.id;state.lastRender='';render();},'plan-button');b.setAttribute('aria-pressed',String(plan.id===state.selected));b.append(node('span',`${(plan.task_ids||[]).length}件の作業 / 版 ${plan.revision}`));planBox.append(b);}}if(!plans.length)planBox.append(node('p','計画がありません。','empty'));
 const plan=plans.find(p=>p.id===state.selected);$('detail-title').textContent=plan?.title||'計画を選んでください';$('plan-revision').textContent=plan?`版 ${plan.revision}`:'';$('plan-note').textContent=plan?'AIが進める範囲は、この計画に含まれる作業だけです。':'一覧から計画を選びます。';
 const selectedRuns=runs.filter(r=>r.plan_id===plan?.id),run=selectedRuns[selectedRuns.length-1];const start=$('start-controls');start.replaceChildren();if(plan){const begin=button(run?'この計画は開始済み':'この計画を開始',()=>act('start',{plan_id:plan.id,revision:plan.revision}),'primary');begin.disabled=state.busy||Boolean(run);start.append(begin);}
 const runBox=$('run-status');runBox.replaceChildren();if(run){runBox.append(node('strong',`担当の状態: ${labels[run.status]||run.status}`));runBox.append(node('span',`担当 ${run.agent_id??'不明'} / 引き継ぎ世代 ${run.epoch??'不明'}`));const controls=node('div',undefined,'actions');const pause=button('一時停止',()=>act('pause',{run_id:run.id})),resume=button('再開',()=>act('resume',{run_id:run.id}));pause.disabled=state.busy||!['active','running','waiting_approval'].includes(run.status);resume.disabled=state.busy||run.status!=='paused';controls.append(pause,resume);runBox.append(controls);}else if(plan)runBox.append(node('span','まだ開始していません。開始後は架空の担当が自動で進めます。'));
 const taskBox=$('tasks');taskBox.replaceChildren();const ordered=(plan?.task_ids||[]).map(tid=>tasks.find(t=>t.id===tid)).filter(Boolean);for(const [index,task] of ordered.entries()){const row=node('article',undefined,'task');row.append(node('span',String(index+1).padStart(2,'0'),'task-number'));const body=node('div');body.append(node('div',task.title,'task-title'));const meta=node('div',undefined,'task-meta');meta.append(status(task.status));if(task.requires_approval)meta.append(node('span','本人の判断あり','muted'));body.append(meta);if(task.result!==null&&task.result!==undefined)body.append(node('p',`成果: ${typeof task.result==='string'?task.result:JSON.stringify(task.result)}`,'muted'));row.append(body);if(task.document_id)row.append(button('根拠の原文を読む',()=>documentOpen(task.document_id),'document-button'));taskBox.append(row);}
 const pending=approvals.filter(a=>selectedRuns.some(r=>r.id===a.run_id)&&['pending','waiting','waiting_approval','pending_approval'].includes(a.status));$('approval-section').hidden=!pending.length;const approvalBox=$('approvals');approvalBox.replaceChildren();for(const approval of pending){const item=node('article',undefined,'approval-item');const task=tasks.find(t=>t.id===approval.task_id);item.append(node('strong',task?.title||approval.task_id),node('p',`確認する指示の版: ${approval.revision}`));const controls=node('div',undefined,'actions');controls.append(button('この内容を承認',()=>act('decide',{approval_id:approval.id,decision:'approve',revision:approval.revision}),'primary'),button('却下する',()=>act('decide',{approval_id:approval.id,decision:'reject',revision:approval.revision}),'danger'));item.append(controls);approvalBox.append(item);}
 const exercise=$('exercise-controls');exercise.replaceChildren();if(run){const stop=button('架空の担当を停止確認',()=>act('stop_agent',{run_id:run.id}),'secondary'),handoff=button('別の架空担当へ引き継ぐ',()=>act('handoff',{run_id:run.id}),'secondary');stop.disabled=state.busy||!['active','running','waiting_approval','paused'].includes(run.status);handoff.disabled=state.busy||run.status!=='agent_stopped';exercise.append(stop,handoff);}else exercise.append(node('span','計画を開始すると試せます。'));
 listEvents('events',snap.events||[]);listEvents('notifications',snap.notifications||[]);$('refresh').disabled=state.busy;
}
async function refresh(){const generation=++state.generation;try{const snap=await api('/api/snapshot');if(generation!==state.generation)return;if(snap.synthetic!==true)throw new Error('合成データの印がないため、操作画面を表示できません。');state.snapshot=snap;render();$('connection').textContent=`最後の確認: ${snap.observed_at||'不明'} / 自動更新中`;if(snap.scheduler_error)message('error','自動進行の処理が停止しました。状態を確認し、結果不明の作業を再送しないでください。');}catch(error){$('connection').textContent='接続を確認できません。表示は最後に取得した状態です。';message('error',error.message);}}
async function poll(){await refresh();state.timer=setTimeout(poll,1200);}
$('refresh').addEventListener('click',refresh);$('close-document').addEventListener('click',()=>{$('document-surface').hidden=true;});window.addEventListener('pagehide',()=>{state.suspended=true;clearTimeout(state.timer);});window.addEventListener('pageshow',()=>{if(state.suspended){state.suspended=false;poll();}});poll();
